async function call(page, op, data = {}) {
	return page.evaluate(({ op, data }) => window.__blockStorageHarness.send(op, data), { op, data });
}

async function observe(page, reset = false) {
	return page.evaluate(operation => window.__blockStorageHarness.observer(operation), reset ? 'reset' : 'snapshot');
}

async function physical(page, storeId) {
	return page.evaluate(id => window.__blockStorageHarness.physical(id), storeId);
}

async function seedLegacy(page, storeId, rows) {
	return page.evaluate(({ storeId, rows }) => window.__blockStorageHarness.seedLegacy(storeId, rows), { storeId, rows });
}

